where 1 = 1

    and t1.status = #{status,jdbcType=INTEGER}


    and t1.datasource_name = #{datasourceName,jdbcType=VARCHAR}


    and t1.datasource_desc = #{datasourceDesc,jdbcType=VARCHAR}


